oxy_webhelp_navlinks = {"rcv_location_management-d39307e11220":{"topics":[{"title":"Editing RCV locations","shortdesc":"<p class=\"shortdesc\">Edit a Rubrik Cloud Vault location to modify settings such as the location name,         proxy configuration, private endpoints or VPC interface endpoints, or IP allow list. Editable         settings vary by cloud provider, such as Azure, AWS, or GCP, and location type, such as data         center, cloud-native, or NAS Cloud Direct.<\/p>","href":"saas\/rcv_editing_locations.html","attributes":{"data-id":"rcv_editing_locations"},"menu":{"hasChildren":false},"tocID":"rcv_editing_locations-d39307e11233","topics":[]},{"title":"Pausing RCV locations","shortdesc":"<p class=\"shortdesc\">You can pause a Rubrik Cloud Vault location to temporarily stop the archiving jobs on         the Rubrik Cloud Vault locations.<\/p>","href":"saas\/rcv_pausing_locations.html","attributes":{"data-id":"rcv_pausing_locations"},"menu":{"hasChildren":false},"tocID":"rcv_pausing_locations-d39307e11244","topics":[]},{"title":"Disabling RCV locations","shortdesc":"<p class=\"shortdesc\">You can stop a Rubrik Cloud Vault location from archiving and any other background         operations that can change data on the archival location.<\/p>","href":"saas\/rcv_disabling_locations.html","attributes":{"data-id":"rcv_disabling_locations"},"menu":{"hasChildren":false},"tocID":"rcv_disabling_locations-d39307e11255","topics":[]},{"title":"Deleting RCV locations","shortdesc":"<p class=\"shortdesc\">Delete a Rubrik Cloud Vault location when you do not need the archived         data.<\/p>","href":"saas\/rcv_deleting_locations.html","attributes":{"data-id":"rcv_deleting_locations"},"menu":{"hasChildren":false},"tocID":"rcv_deleting_locations-d39307e11266","topics":[]},{"title":"Converting an RCV location to the Recovery tier","shortdesc":"<p class=\"shortdesc\">Convert an existing cloud-native Rubrik Cloud Vault location from the Backup tier to         the Recovery tier to support advanced security operations.<\/p>","href":"saas\/rcv_converting_location_tier.html","attributes":{"data-id":"rcv_converting_location_tier"},"menu":{"hasChildren":false},"tocID":"rcv_converting_location_tier-d39307e11277","topics":[]},{"title":"Converting an RCV location to the Archive tier","shortdesc":"<p class=\"shortdesc\">Convert an existing cloud-native Rubrik Cloud Vault location from the Backup tier to         the Archive tier to support long-term data retention and compliance         requirements.<\/p>","href":"saas\/rcv_converting_backup_to_archive_tier.html","attributes":{"data-id":"rcv_converting_backup_to_archive_tier"},"menu":{"hasChildren":false},"tocID":"rcv_converting_backup_to_archive_tier-d39307e11288","topics":[]},{"title":"RCV redundancy conversion","shortdesc":"<p class=\"shortdesc\">You can convert the storage redundancy of an existing RCV Backup tier location on Azure to a         different type.<\/p>","href":"saas\/rcv_redundancy_conversion.html","attributes":{"data-id":"rcv_redundancy_conversion"},"menu":{"hasChildren":false},"tocID":"rcv_redundancy_conversion-d39307e11299","next":"rcv_redundancy_conversion-d39307e11299"},{"title":"Migration of archival locations to RCV","shortdesc":"<p class=\"shortdesc\">You can migrate existing archival location data from Amazon S3, S3-compatible, or         Azure Blob storage to Rubrik Cloud Vault by using a supported migration tool with assistance         from Rubrik Professional Services.<\/p>","href":"saas\/migration_arch_loc_rcv_2.html","attributes":{"data-id":"migration_arch_loc_rcv"},"menu":{"hasChildren":false},"tocID":"migration_arch_loc_rcv-d39307e11321","topics":[]},{"title":"Immutability conversion for Azure RCV locations","shortdesc":"<p class=\"shortdesc\">Using <span class=\"ph\">RSC<\/span>, you can convert non-immutable data center RCV locations on         Azure to immutable locations.<\/p>","href":"saas\/rcv_immutability_conv_azure_loc.html","attributes":{"data-id":"rcv_immutability_conv_azure_loc"},"menu":{"hasChildren":false},"tocID":"rcv_immutability_conv_azure_loc-d39307e11332","next":"rcv_immutability_conv_azure_loc-d39307e11332"}]}};